    "lang.eyebrow": "Sprachen · 28",
    "lang.foot": "Falsche Übersetzung entdeckt? <a href=\"https://github.com/andriydruk/LMPlayground/tree/main/app/src/main/res\">Bitte öffne einen PR auf GitHub</a>.",
    "lang.locales": "Sprachen",
    "lang.sub": "Die ganze App ist in 28 Sprachen übersetzt. Beim ersten Start wählen wir ein Modell aus, das deine Sprache spricht.",
    "lang.title": "Spricht deine Sprache.<br/>Direkt ab Werk.",
    "logos.label": "Unterstützt offene Gewichte von",
    "models.eyebrow": "Modell-Bibliothek · 40+",
    "models.other_models": "Andere Modelle",
    "models.sub": "Durchsuche von der Community erstellte Modelle, die für mobile Geräte optimiert sind — klein genug für dein Handy, leistungsstark genug, um nützlich zu sein.",
    "models.supports_your_language": "Unterstützt deine Sprache",
