    "lang.eyebrow": "Mga Wika · 28",
    "lang.foot": "May nakitang maling salin? <a href=\"https://github.com/andriydruk/LMPlayground/tree/main/app/src/main/res\">Magbukas po ng PR sa GitHub</a>.",
    "lang.locales": "mga wika",
