    "models.other_models": "Model lainnya",
    "models.sub": "Jelajahi model buatan komunitas yang dioptimalkan untuk ponsel — cukup ringkas untuk muat di ponsel, cukup kuat untuk berguna.",
    "models.supports_your_language": "Mendukung bahasa Anda",
