    "lang.eyebrow": "Lingue · 28",
    "lang.foot": "Hai notato una traduzione sbagliata? <a href=\"https://github.com/andriydruk/LMPlayground/tree/main/app/src/main/res\">Apri una PR su GitHub</a>.",
    "lang.locales": "lingue",
