    "hero.sub": "Tiada awan, tiada Internet, tiada penjejakan.",
    "hero.title": "Jalankan model bahasa besar<br/>pada telefon <em>anda</em>.",
    "how.eyebrow": "Cara berfungsi",
    "how.step1.body": "Layari senarai pilihan atau tampal URL model anda sendiri. Saiz dari 267 MB hingga 5.4 GB.",
