    "lang.eyebrow": "Bahasa · 28",
    "lang.foot": "Nampak terjemahan yang salah? <a href=\"https://github.com/andriydruk/LMPlayground/tree/main/app/src/main/res\">Sila buka PR di GitHub</a>.",
    "lang.locales": "bahasa",
    "lang.sub": "Seluruh aplikasi diterjemahkan ke dalam 28 bahasa. Pada pelancaran pertama, kami akan pilih model yang bercakap bahasa anda.",
    "lang.title": "Bercakap bahasa anda.<br/>Daripada permulaan.",
    "logos.label": "Menjalankan pemberat terbuka daripada",
    "models.eyebrow": "Pustaka model · 40+",
    "models.other_models": "Model lain",
    "models.sub": "Layari model komuniti yang dioptimumkan untuk mudah alih — cukup padat untuk muat pada telefon, cukup berkuasa untuk berguna.",
    "models.supports_your_language": "Menyokong bahasa anda",
    "models.tab.all": "Semua",
    "models.tab.reason": "Penaakulan",
