    "models.eyebrow": "Modelbibliotheek · 40+",
    "models.other_models": "Andere modellen",
    "models.sub": "Verken community-modellen geoptimaliseerd voor mobiel — compact genoeg voor je telefoon, krachtig genoeg om nuttig te zijn.",
    "models.supports_your_language": "Ondersteunt jouw taal",
