    "lang.eyebrow": "Diller · 28",
    "lang.foot": "Yanlış bir çeviri mi gördün? <a href=\"https://github.com/andriydruk/LMPlayground/tree/main/app/src/main/res\">Lütfen GitHub'da bir PR aç</a>.",
    "lang.locales": "dil",
