    "lang.title": "Senin dilini konuşur.<br/>Kutudan çıktığı gibi.",
    "logos.label": "Açık ağırlıkları çalıştırır",
    "models.eyebrow": "Model kütüphanesi · 40+",
    "models.other_models": "Diğer modeller",
    "models.sub": "Topluluk yapımı, mobil için optimize edilmiş modelleri keşfet — telefona sığacak kadar küçük, faydalı olacak kadar güçlü.",
    "models.supports_your_language": "Dilinizi destekler",
